1	<script lang="ts">
2	  import { onMount } from 'svelte';
3	  import { apiFetch, ApiError } from '../lib/api';
4	  import { getWorksheetData } from '../lib/tableau';
5	  import { sessionStore } from '../stores/session.svelte';
6	  import { dataStore } from '../stores/data.svelte';
7	
8	  const sessionHeaders = (): Record<string, string> =>
9	    sessionStore.sessionId ? { 'X-Autom9-Session': sessionStore.sessionId } : {};
10	
11	  // Returns worksheet name from config, or null if not set.
12	  // Throws ApiError/Error if the config endpoint is unreachable.
13	  async function loadWorksheetConfig(): Promise<string | null> {
14	    const config = await apiFetch<{ data: { data_panel?: { worksheet_name?: string } } | null }>(
15	      '/api/config/workflow'
16	    );
17	    return config.data?.data_panel?.worksheet_name ?? null;
18	  }
19	
20	  async function loadWorksheetData(worksheetName: string): Promise<void> {
21	    dataStore.worksheetState = 'loading';
22	    try {
23	      dataStore.worksheetRows = await getWorksheetData(worksheetName);
24	      dataStore.worksheetState = 'done';
25	    } catch {
26	      // Generic message — never expose raw error details to the consultant (AC4)
27	      dataStore.worksheetError = 'Could not load worksheet data';
28	      dataStore.worksheetState = 'error';
29	    }
30	  }
31	
32	  async function loadTasks(): Promise<void> {
33	    dataStore.tasksState = 'loading';
34	    try {
35	      const response = await apiFetch<{ data: Array<{ text: string }> }>('/api/data/tasks', {
36	        headers: sessionHeaders(),
37	      });
38	      dataStore.tasks = response.data;
39	      dataStore.tasksState = 'done';
40	    } catch (err) {
41	      const msg =
42	        err instanceof ApiError
43	          ? err.message
44	          : err instanceof Error
45	            ? err.message
46	            : 'Could not load task list';
47	      dataStore.tasksError = msg;
48	      dataStore.tasksState = 'error';
49	    }
50	  }
51	
52	  onMount(() => {
53	    let active = true; // abort guard — prevents stale promise writes on rapid remount
54	
55	    (async () => {
56	      // Distinguish config fetch failure from worksheet simply not being configured
57	      let worksheetName: string | null = null;
58	      let configFetchError: string | null = null;
59	      try {
60	        worksheetName = await loadWorksheetConfig();
61	      } catch (err) {
62	        configFetchError =
63	          err instanceof ApiError ? err.message : 'Could not load configuration';
64	      }
65	
66	      if (!active) return;
67	
68	      // Both fetches run independently — one failure must not block the other (NFR9)
69	      const worksheetPromise = worksheetName
70	        ? loadWorksheetData(worksheetName)
71	        : (() => {
72	            dataStore.worksheetError = configFetchError ?? 'Worksheet name not configured';
73	            dataStore.worksheetState = 'error';
74	            return Promise.resolve();
75	          })();
76	
77	      await Promise.allSettled([worksheetPromise, loadTasks()]);
78	    })();
79	
80	    return () => {
81	      active = false; // cancel on unmount
82	    };
83	  });
84	</script>
85	
86	<div class="data-panel">
87	  <!-- Open days / scheduled engagements from Tableau worksheet -->
88	  <section class="panel-section">
89	    <h3>Open Days &amp; Engagements</h3>
90	    {#if dataStore.worksheetState === 'loading'}
91	      <p class="loading">Loading…</p>
92	    {:else if dataStore.worksheetState === 'error'}
93	      <p class="error">{dataStore.worksheetError}</p>
94	    {:else if dataStore.worksheetRows.length === 0}
95	      <p class="empty">No data available</p>
96	    {:else}
97	      <table>
98	        <thead>
99	          <tr>
100	            {#each Object.keys(dataStore.worksheetRows[0]) as col}
101	              <th>{col}</th>
102	            {/each}
103	          </tr>
104	        </thead>
105	        <tbody>
106	          {#each dataStore.worksheetRows as row}
107	            <tr>
108	              {#each Object.values(row) as val}
109	                <td>{val}</td>
110	              {/each}
111	            </tr>
112	          {/each}
113	        </tbody>
114	      </table>
115	    {/if}
116	  </section>
117	
118	  <!-- Task list from Google Docs -->
119	  <section class="panel-section">
120	    <h3>Task List</h3>
121	    {#if dataStore.tasksState === 'loading'}
122	      <p class="loading">Loading…</p>
123	    {:else if dataStore.tasksState === 'error'}
124	      <p class="error">{dataStore.tasksError}</p>
125	    {:else if dataStore.tasks.length === 0}
126	      <p class="empty">No tasks available</p>
127	    {:else}
128	      <ul>
129	        {#each dataStore.tasks as task}
130	          <li>{task.text}</li>
131	        {/each}
132	      </ul>
133	    {/if}
134	  </section>
135	</div>
136	
137	<style>
138	  .data-panel {
139	    font-family: sans-serif;
140	    padding: 0.75rem;
141	  }
142	  .panel-section {
143	    margin-bottom: 1.25rem;
144	  }
145	  h3 {
146	    font-size: 0.875rem;
147	    font-weight: 600;
148	    margin: 0 0 0.5rem;
149	    text-transform: uppercase;
150	    letter-spacing: 0.05em;
151	    color: #444;
152	  }
153	  .loading { color: #666; font-style: italic; }
154	  .error { color: #c00; }
155	  .empty { color: #888; }
156	  table { border-collapse: collapse; width: 100%; font-size: 0.8rem; }
157	  th, td { border: 1px solid #ddd; padding: 0.25rem 0.5rem; text-align: left; }
158	  th { background: #f5f5f5; }
159	  ul { margin: 0; padding-left: 1.25rem; font-size: 0.875rem; }
160	  li { margin-bottom: 0.25rem; }
161	</style>
